using System;
using System.IO;
using System.Runtime.InteropServices;
public static class FlagVisibility {
    [StructLayout(LayoutKind.Sequential)] struct IoStatus { public IntPtr Status, Information; }
    [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)] static extern IntPtr CreateFileW(string path, uint access, uint share, IntPtr security, uint disposition, uint flags, IntPtr template);
    [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr file);
    [DllImport("kernel32.dll", SetLastError=true)] static extern bool GetFileInformationByHandleEx(IntPtr file, int kind, IntPtr output, uint size);
    [DllImport("ntdll.dll")] static extern int NtQueryInformationFile(IntPtr file, out IoStatus status, IntPtr output, uint size, int kind);
    public sealed class Observation { public uint Mode; public bool DeletePending, RequestedDeleteOnClose, RemovedWhenClosed; }
    public static Observation Run() {
        if (IntPtr.Size != 8) throw new PlatformNotSupportedException("x64 required");
        string path = Path.Combine(Path.GetTempPath(), "voldiq-mode-" + Guid.NewGuid().ToString("N"));
        IntPtr file = CreateFileW(path, 0x00010081, 1, IntPtr.Zero, 1, 0x04300000, IntPtr.Zero);
        if (file == new IntPtr(-1)) throw new IOException("CreateNew failed: " + Marshal.GetLastWin32Error());
        IntPtr mode = IntPtr.Zero, standard = IntPtr.Zero;
        var result = new Observation { RequestedDeleteOnClose = true };
        try {
            mode = Marshal.AllocHGlobal(4); standard = Marshal.AllocHGlobal(24);
            int status = NtQueryInformationFile(file, out IoStatus io, mode, 4, 16);
            if (status != 0) throw new IOException("Mode query failed: " + status);
            if (!GetFileInformationByHandleEx(file, 1, standard, 24)) throw new IOException("Standard query failed: " + Marshal.GetLastWin32Error());
            result.Mode = (uint)Marshal.ReadInt32(mode);
            result.DeletePending = Marshal.ReadByte(standard, 20) != 0;
        } finally {
            if (mode != IntPtr.Zero) Marshal.FreeHGlobal(mode);
            if (standard != IntPtr.Zero) Marshal.FreeHGlobal(standard);
            CloseHandle(file);
        }
        result.RemovedWhenClosed = !File.Exists(path);
        if (!result.RemovedWhenClosed) throw new IOException("Owned empty fixture remains: " + Path.GetFileName(path));
        return result;
    }
}
